-- DMF0003 메타 전 축 (딕셔너리 전수 스윕 산출 — 손나열 아님)
-- 감사컬럼 = 'admin' 고정 / 날짜 = SYSDATE
-- 각 축은 DELETE(동일 조건) → INSERT 로 멱등. 삭제범위 = 삽입범위.
-- ⚠ LIKE '%DMF0003%' 라 파생 메뉴(DMF0003, DMF0003_1) 행도 함께 포함된다.
-- ⊘ 제외: SCM_ADM_BTNMPG_BAK_DMF0003_RENAME — 백업 테이블 — 클라우드 미존재. 이관 대상 아님
-- ⊘ 제외: SCM_ADM_LOOKUP_MASTER_DETAIL_H — 이력(History) 테이블 — 원장이 아니라 변경 이력. 이관 대상 아님
-- ⊘ 제외: SCM_ADM_PROC_M_BAK_20260612_153917 — 백업 테이블(일자 스냅샷) — 이관 대상 아님
-- ⊘ 제외: SCM_ADM_SMS_MAIL_SEND_LOG — 발송 로그 — 런타임 산출물. 이관 대상 아님
-- ⊘ 제외: SCM_ADM_UGBTN_BAK_DMF0003_RENAME — 백업 테이블 — 클라우드 미존재. 이관 대상 아님
-- ⊘ 제외: SCM_ADM_USER_MNU_SRCH_COND_M — 사용자 개인화 조회조건 — 계정별 데이터라 환경 간 이관 금지(TITLESET_USER 동일 규약)
SET DEFINE OFF

-- ═══ SCM_ADM_API_M (26 rows) — 매칭 컬럼: API_ID, API_MSG_ID, API_MSG_DESC, API_URL
DELETE FROM SCM_ADM_API_M WHERE "API_ID" LIKE '%DMF0003%' OR "API_MSG_ID" LIKE '%DMF0003%' OR "API_MSG_DESC" LIKE '%DMF0003%' OR "API_URL" LIKE '%DMF0003%';

-- ═══ SCM_ADM_CMBO_SQL_M (20 rows) — 매칭 컬럼: SQL_ID, SQL_NM, SQL_DTL_CTN
DELETE FROM SCM_ADM_CMBO_SQL_M WHERE "SQL_ID" LIKE '%DMF0003%' OR "SQL_NM" LIKE '%DMF0003%' OR "SQL_DTL_CTN" LIKE '%DMF0003%';
SELECT DISTINCT A.SCM_SITE_ID AS CODE, A.SCM_SITE_ID AS NAME, 2 AS SORT_ORDER
FROM SCM_MST_SITE A
WHERE A.SITE_TYPE = ''SALES'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND A.DIVISION_ID <> ''40''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || A.DIVISION_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || A.END_CUSTOMER || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT DISTINCT A.SCM_SITE_ID, A.SCM_SITE_ID, 2
FROM SCM_MST_SITE A
LEFT JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
LEFT JOIN (SELECT DISTINCT U.USER_ID, U.DEPT_ID FROM SCM_MST_SSO_USER_INFO U JOIN SCM_MST_SSO_DEPT_INFO D2 ON U.DEPT_ID = D2.DEPT_ID) C
  ON B.OWNER = C.USER_ID
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND NVL(A.OPERATION_GROUP, '' '') <> ''W''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '',40,'') > 0)
  AND (NVL(TRIM(@deptId), ''ALL'') = ''ALL'' OR INSTR('','' || @deptId || '','', '','' || C.DEPT_ID || '','') > 0)
  AND (NVL(TRIM(@endCustomer), ''ALL'') = ''ALL'' OR INSTR('','' || @endCustomer || '','', '','' || B.PROJECT_CODE || '','') > 0)
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
UNION ALL
SELECT L.SEGMENT1, B.SITE_DESCRIPTION, 1
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
JOIN SCM_MST_SITE B ON L.SEGMENT3 = B.DIVISION_ID AND L.SEGMENT1 = B.SCM_SITE_ID
WHERE L.LOOKUP_TYPE = ''AS_SITE_PLANT'' AND L.VALID_YN = ''Y'' AND B.VALID_YN = ''Y''
  AND (NVL(TRIM(@divisionId), ''ALL'') = ''ALL'' OR INSTR('','' || @divisionId || '','', '','' || L.SEGMENT3 || '','') > 0)
) ORDER BY SORT_ORDER, CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
SELECT DISTINCT A.DIVISION_ID, C.DEPT_ID,
       A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MST_SITE_ITEM A
JOIN SCM_MST_SSO_USER_INFO B
  ON B.USER_ID = TRIM(CASE WHEN INSTR(A.OWNER, '','') > 0
                           THEN SUBSTR(A.OWNER, 1, INSTR(A.OWNER, '','') - 1) ELSE A.OWNER END)
JOIN SCM_MST_SSO_DEPT_INFO C ON C.DEPT_ID = B.DEPT_ID
LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D
  ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2
 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y'' AND A.PROJECT_CODE IS NOT NULL
UNION
SELECT ''40'', ''-'', SEGMENT2, SEGMENT3
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''END_CUSTOMER'' AND SEGMENT1 = ''40''
  AND SEGMENT2 <> ''-'' AND VALID_YN = ''Y''
) ORDER BY CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
       NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME
FROM SCM_MST_SITE A
LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D
  ON A.DIVISION_ID = D.SEGMENT1 AND A.END_CUSTOMER = D.SEGMENT2
 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.END_CUSTOMER IS NOT NULL
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
                        WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
  AND ( EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L JOIN SCM_MGR.SCM_ADM_USER_GR_MPG_M G ON G.USER_GR_ID = L.SEGMENT1 WHERE L.LOOKUP_TYPE = ''GET_ADMIN_GROUP'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 IN (''ALL'',''DMF0003'') AND G.USER_ID = @sesUserId AND G.USE_YN = ''Y'')
     OR A.DEPT_ID IN (
          SELECT L.SEGMENT3 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
          WHERE L.LOOKUP_TYPE = ''PM_TEAM_MAPPING'' AND L.VALID_YN = ''Y''
            AND L.SEGMENT1 IN (SELECT U.DEPT_ID FROM TB_FX_USER U WHERE U.USERID = @sesUserId)
          UNION
          SELECT U.DEPT_ID FROM TB_FX_USER U WHERE U.USERID = @sesUserId))
ORDER BY CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
     , SEGMENT2 AS NAME
FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE  LOOKUP_TYPE = ''MKT_FCST_UNIT_QTY''
AND    VALID_YN = ''Y''
ORDER BY DISPLAY_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
FROM SCM_MST_SITE A
WHERE A.SITE_TYPE = ''SALES''
  AND A.VALID_YN = ''Y''
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
                        WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
  AND ( EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L JOIN SCM_MGR.SCM_ADM_USER_GR_MPG_M G ON G.USER_GR_ID = L.SEGMENT1 WHERE L.LOOKUP_TYPE = ''GET_ADMIN_GROUP'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 IN (''ALL'',''DMF0003'') AND G.USER_ID = @sesUserId AND G.USE_YN = ''Y'')
     OR A.DEPT_ID IN (
          SELECT L.SEGMENT3 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
          WHERE L.LOOKUP_TYPE = ''PM_TEAM_MAPPING'' AND L.VALID_YN = ''Y''
            AND L.SEGMENT1 IN (SELECT U.DEPT_ID FROM TB_FX_USER U WHERE U.USERID = @sesUserId)
          UNION
          SELECT U.DEPT_ID FROM TB_FX_USER U WHERE U.USERID = @sesUserId))
ORDER BY CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
       S.SCM_SITE_ID AS CODE
     , S.SCM_SITE_ID AS NAME
FROM   SCM_MST_SITE S
INNER JOIN (SELECT DISTINCT I.DIVISION_ID, I.COMPANY_ID
                 , (CASE WHEN I.SCP_OPERATION_GROUP = ''E'' THEN ''A'' ELSE I.SCP_OPERATION_GROUP END) AS SCP_OPERATION_GROUP
            FROM   SCM_MST_PROJECT_ITEM SI
            INNER JOIN SCM_MST_ITEM_SN I
                ON SI.ITEM_ID = I.ITEM_ID
            WHERE  I.ITEM_TYPE IS NOT NULL
            AND    (@divisionId IS NULL OR @divisionId = '''' OR SI.DIVISION_ID = @divisionId)
            AND    (@projectCode IS NULL OR @projectCode = '''' OR SI.PROJECT_CODE = @projectCode)
            AND    (@itemId IS NULL OR @itemId = '''' OR SI.ITEM_ID = @itemId)
           ) SS
    ON  S.DIVISION_ID = SS.DIVISION_ID
    AND S.OPERATION_GROUP = NVL(SS.SCP_OPERATION_GROUP, S.OPERATION_GROUP)
    AND S.COMPANY_ID = SS.COMPANY_ID
WHERE  S.SITE_TYPE = ''PLANT''
AND    (@divisionId IS NULL OR @divisionId = '''' OR S.DIVISION_ID = @divisionId)
ORDER BY 1, 2', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
FROM SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE LOOKUP_TYPE = ''AS_INCOTERMS''
  AND VALID_YN = ''Y''
  AND SEGMENT1 = @divisionId
ORDER BY SEGMENT2', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
WHERE L.LOOKUP_TYPE = ''DM_BIZ_TYPE''
UNION ALL
SELECT DISTINCT P.DIVISION_ID, P.BIZ_TYPE AS CODE, P.BIZ_TYPE_NAME AS NAME
FROM SCM_MST_PROJECT P
WHERE TRIM(P.BIZ_TYPE_NAME) IS NOT NULL
ORDER BY DIVISION_ID, CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
     , CASE @langCd WHEN ''EN'' THEN C.DEPT_NAME_EN WHEN ''CN'' THEN C.DEPT_NAME_CN ELSE C.DEPT_NAME_KO END AS NAME
FROM SCM_MST_SITE_ITEM A, SCM_MST_SSO_USER_INFO B, SCM_MST_SSO_DEPT_INFO C
WHERE B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))
  AND B.DEPT_ID = C.DEPT_ID
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
ORDER BY DIVISION_ID, NAME, CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID, A.PROJECT_CODE AS CODE, NVL(D.SEGMENT3, A.PROJECT_CODE) AS NAME
FROM SCM_MST_SITE_ITEM A
JOIN SCM_MST_SSO_USER_INFO B ON B.USER_ID = TRIM(REGEXP_SUBSTR(A.OWNER, ''[^,]+'', 1, 1))
JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID
LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D
  ON A.DIVISION_ID = D.SEGMENT1 AND A.PROJECT_CODE = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.DIVISION_ID = ''40'' AND A.VALID_YN = ''Y''
UNION
SELECT L.SEGMENT1, NULL, L.SEGMENT2, L.SEGMENT3
FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
WHERE L.LOOKUP_TYPE = ''END_CUSTOMER'' AND L.SEGMENT2 <> ''-'' AND L.VALID_YN = ''Y'' AND L.SEGMENT1 = ''40''
UNION ALL
SELECT DISTINCT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, NVL(D.SEGMENT3, A.END_CUSTOMER)
FROM SCM_MST_SITE A
LEFT JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D
  ON A.DIVISION_ID = D.SEGMENT1 AND A.END_CUSTOMER = D.SEGMENT2 AND D.LOOKUP_TYPE = ''END_CUSTOMER'' AND D.VALID_YN = ''Y''
WHERE A.END_CUSTOMER IS NOT NULL
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
) ORDER BY DIVISION_ID, CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
MAPSET AS (SELECT L.SEGMENT3 AS DEPT_ID FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
           WHERE L.LOOKUP_TYPE = ''PM_TEAM_MAPPING'' AND L.VALID_YN = ''Y''
             AND L.SEGMENT1 IN (SELECT DEPT_ID FROM ME)
           UNION SELECT DEPT_ID FROM ME),
F AS (SELECT (SELECT COUNT(*) FROM MAPSET) AS TEAM_CNT,
             (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L JOIN SCM_MGR.SCM_ADM_USER_GR_MPG_M G ON G.USER_GR_ID = L.SEGMENT1 WHERE L.LOOKUP_TYPE = ''GET_ADMIN_GROUP'' AND L.VALID_YN = ''Y'' AND L.SEGMENT2 IN (''ALL'',''DMF0003'') AND G.USER_ID = @sesUserId AND G.USE_YN = ''Y'') AS IS_ADMIN
      FROM DUAL)
SELECT DISTINCT DIVISION_ID, CODE, NAME FROM (
SELECT A.DIVISION_ID, B.DEPT_ID AS CODE, B.DEPT_NAME_KO AS NAME
FROM SCM_MST_SITE A JOIN SCM_MST_SSO_DEPT_INFO B ON A.DEPT_ID = B.DEPT_ID CROSS JOIN F
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID <> ''40'' AND F.TEAM_CNT <= 1
  AND A.DIVISION_ID IN (SELECT UNIT_ID FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
                        WHERE USER_ID = @sesUserId AND UNIT_TP_CD = ''D'' AND USE_YN = ''Y'')
  AND (F.IS_ADMIN > 0 OR B.DEPT_ID IN (SELECT DEPT_ID FROM ME))
UNION
SELECT ''40'', C.DEPT_ID, C.DEPT_NAME_KO
FROM SCM_MST_SITE_ITEM A JOIN SCM_MST_SSO_USER_INFO B ON A.OWNER = B.USER_ID
JOIN SCM_MST_SSO_DEPT_INFO C ON B.DEPT_ID = C.DEPT_ID CROSS JOIN F
WHERE A.DIVISION_ID = ''40'' AND F.TEAM_CNT <= 1
  AND (F.IS_ADMIN > 0 OR C.DEPT_ID IN (SELECT DEPT_ID FROM ME))
UNION
SELECT A.DIVISION_ID, B.DEPT_ID, B.DEPT_NAME_KO
FROM SCM_MST_SITE A JOIN SCM_MST_SSO_DEPT_INFO B ON A.DEPT_ID = B.DEPT_ID CROSS JOIN F
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID <> ''40'' AND F.TEAM_CNT > 1
  AND B.DEPT_ID IN (SELECT DEPT_ID FROM MAPSET)
UNION
SELECT A.DIVISION_ID, B2.DEPT_ID, B2.DEPT_NAME_KO
FROM SCM_MST_SITE A
JOIN SCM_MST_SITE_ITEM I ON A.DIVISION_ID = I.DIVISION_ID AND A.SCM_SITE_ID = I.SCM_SITE_ID
JOIN SCM_MST_SSO_USER_INFO SU ON SU.USER_ID = I.OWNER
JOIN SCM_MST_SSO_DEPT_INFO B2 ON B2.DEPT_ID = SU.DEPT_ID CROSS JOIN F
WHERE A.SITE_TYPE = ''SALES'' AND A.DIVISION_ID = ''40'' AND F.TEAM_CNT > 1
  AND B2.DEPT_ID IN (SELECT DEPT_ID FROM MAPSET)
) ORDER BY CODE', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
      , SEGMENT2  AS NAME
FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
WHERE  1 = 1
AND    LOOKUP_TYPE = ''REPORT_BUCKET_TYPE_CODE''
ORDER BY DISPLAY_SEQ', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);

-- ═══ SCM_ADM_EXCEL_COLUMNS (1 rows) — 매칭 컬럼: PROGRAM_ID, STORAGE_SQL_ID
DELETE FROM SCM_ADM_EXCEL_COLUMNS WHERE "PROGRAM_ID" LIKE '%DMF0003%' OR "STORAGE_SQL_ID" LIKE '%DMF0003%';

-- ═══ SCM_ADM_LOOKUP_MASTER_DETAIL (12 rows) — 매칭 컬럼: SEGMENT1, SEGMENT2, DESCRIPTION
DELETE FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE "SEGMENT1" LIKE '%DMF0003%' OR "SEGMENT2" LIKE '%DMF0003%' OR "DESCRIPTION" LIKE '%DMF0003%';

-- ═══ SCM_ADM_MNU_BTN_MPG_M (26 rows) — 매칭 컬럼: MNU_ID, API_ID
DELETE FROM SCM_ADM_MNU_BTN_MPG_M WHERE "MNU_ID" LIKE '%DMF0003%' OR "API_ID" LIKE '%DMF0003%';

-- ═══ SCM_ADM_MNU_M (2 rows) — 매칭 컬럼: MNU_ID
DELETE FROM SCM_ADM_MNU_M WHERE "MNU_ID" LIKE '%DMF0003%';

-- ═══ SCM_ADM_MSG_M (33 rows) — 매칭 컬럼: MSG_ID
DELETE FROM SCM_ADM_MSG_M WHERE "MSG_ID" LIKE '%DMF0003%';

-- ═══ SCM_ADM_PROC_M (186 rows) — 매칭 컬럼: PROC_NM
DELETE FROM SCM_ADM_PROC_M WHERE "PROC_NM" LIKE '%DMF0003%';

-- ═══ SCM_ADM_PROGRAM (3 rows) — 매칭 컬럼: PROGRAM_ID, PROGRAM_PATH, CLASS_NAME
DELETE FROM SCM_ADM_PROGRAM WHERE "PROGRAM_ID" LIKE '%DMF0003%' OR "PROGRAM_PATH" LIKE '%DMF0003%' OR "CLASS_NAME" LIKE '%DMF0003%';

-- ═══ SCM_ADM_USER_GR_MNU_BTN_MPG_M (203 rows) — 매칭 컬럼: MNU_ID
DELETE FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE "MNU_ID" LIKE '%DMF0003%';

-- ═══ SCM_ADM_USER_GR_MNU_MPG_M (9 rows) — 매칭 컬럼: MNU_ID
DELETE FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE "MNU_ID" LIKE '%DMF0003%';

COMMIT;
