INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES ('MktFcstEditableDivision', 'ALL', 'MKT FCST 편집가능 Division', 'SELECT SEGMENT2 AS CODE, SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''DM_UI_EDITABLE_DIVISION'' AND SEGMENT1 = ''DMF0003'' AND ATTRIBUTE1 = ''Y'' AND VALID_YN = ''Y'' ORDER BY SEGMENT2', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
