INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES ('ReportBucketType', 'ALL', 'Report Bucket (AS-IS DMF0003_GET_REPORT_BUCKET_TYPE_CODE — ONLY_WEEKLY 포함)', 'SELECT SEGMENT1  AS CODE
INSERT INTO SCM_ADM_CMBO_SQL_M (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES ('Measure', 'DM', '[C] AS-IS @Code=''Measure'' 수작업 통합 변환 — @Param1→@mnuId + SHEET_NAME=@Param2 제거·', 'SELECT DISTINCT A.COLUMN_NAME AS CODE, CASE WHEN A.COLUMN_NAME = ''CUST_FCST_EDI_ORG'' THEN '' └ '' || ''EDI[Org.]'' WHEN A.COLUMN_NAME = ''CUST_FCST_EDI'' THEN '' └ '' || ''EDI'' ELSE A.COLUMN_LABEL_NAME END AS NAME FROM SCM_MGR.SCM_MST_SHEET_MEASURE A WHERE A.PROGRAM_ID = @mnuId AND A.VALID_YN = ''Y'' UNION ALL SELECT MEASURE AS CODE, '' └ '' || MEASURE AS NAME FROM SCM_MGR.DM_MST_CUSTOMER_FCST WHERE VALID_YN = ''Y'' AND MEASURE IS NOT NULL AND MEASURE_GROUP = ''CUST_FCST'' AND @mnuId IN (''DMF0003'', ''DMF0035'', ''DMF0003_TEST'') GROUP BY MEASURE UNION ALL SELECT ''Immidiate'', ''    └ '' || ''Immidiate'' FROM DUAL UNION ALL SELECT ''Planning_Forecast'', ''    └ '' || ''Planning_Forecast'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement'', ''    └ '' || ''Commercial_Agreement'' FROM DUAL UNION ALL SELECT ''Firm_Temp'', ''    └ '' || ''Firm_Temp'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp'', ''    └ '' || ''Manumacturing_Material_Temp'' FROM DUAL UNION ALL SELECT ''Material_Temp'', ''    └ '' || ''Material_Temp'' FROM DUAL UNION ALL SELECT ''Backorder'', ''    └ '' || ''Backorder'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[P+P]'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[P+P]'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Immidiate[Org.]'', ''    └ '' || ''Immidiate[Org.]'' FROM DUAL UNION ALL SELECT ''Planning_Forecast[Org.]'', ''    └ '' || ''Planning_Forecast[Org.]'' FROM DUAL UNION ALL SELECT ''Commercial_Agreement[Org.]'', ''    └ '' || ''Commercial_Agreement[Org.]'' FROM DUAL UNION ALL SELECT ''Firm_Temp[Org.]'', ''    └ '' || ''Firm_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Manumacturing_Material_Temp[Org.]'', ''    └ '' || ''Manumacturing_Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Material_Temp[Org.]'', ''    └ '' || ''Material_Temp[Org.]'' FROM DUAL UNION ALL SELECT ''Backorder[Org.]'', ''    └ '' || ''Backorder[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL[Org.]'', '' └ '' || ''EXCEL[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA[Org.]'', '' └ '' || ''RPA[Org.]'' FROM DUAL UNION ALL SELECT ''Cust.FCST_EXCEL'', '' └ '' || ''EXCEL'' FROM DUAL UNION ALL SELECT ''Cust.FCST_RPA'', '' └ '' || ''RPA'' FROM DUAL UNION ALL SELECT ''Ship Plan'', ''Ship Plan'' FROM DUAL UNION ALL SELECT ''CUST_FCST_EDI'', '' └ '' || ''EDI'' FROM DUAL', 'Y', 'admin', SYSDATE, 'admin', SYSDATE);
